with Ada.Command_Line;
with Ada.Text_IO;
with Ada.Containers.Vectors;
with Ada.Strings.Unbounded;
with Ada.Characters.Handling;

procedure Main is
   package US renames Ada.Strings.Unbounded;
   package CH renames Ada.Characters.Handling;

   package String_Vectors is new Ada.Containers.Vectors
     (Index_Type   => Positive,
      Element_Type => US.Unbounded_String);

   use Ada.Command_Line;
   use Ada.Text_IO;
   use String_Vectors;

   function Less (Left, Right : US.Unbounded_String) return Boolean is
      Ls : constant String := US.To_String (Left);
      Rs : constant String := US.To_String (Right);

      function To_Lower_String (S : String) return String is
         R : String (S'Range);
      begin
         for I in S'Range loop
            R (I) := CH.To_Lower (S (I));
         end loop;
         return R;
      end To_Lower_String;

      Ll : constant Natural := Ls'Length;
      Rl : constant Natural := Rs'Length;
   begin
      if Ll /= Rl then
         return Ll > Rl;
      else
         return To_Lower_String (Ls) < To_Lower_String (Rs);
      end if;
   end Less;

   procedure Sort is new String_Vectors.Generic_Sorting (Before => Less);

   V : Vector;
begin
   for I in 1 .. Argument_Count loop
      V.Append (US.To_Unbounded_String (Argument (I)));
   end loop;

   Sort (V);

   for I in V.First_Index .. V.Last_Index loop
      Put_Line (US.To_String (V (I)));
   end loop;
end Main;

