with Ada.Command_Line;
with Ada.Strings.Fixed;
with Ada.Strings.Maps;
with Ada.Strings.Unbounded;
with Ada.Containers;
with Ada.Containers.Vectors;
with Ada.Text_IO;

procedure Main is
   package US renames Ada.Strings.Unbounded;
   package SF renames Ada.Strings.Fixed;
   package SM renames Ada.Strings.Maps;

   package String_Vectors is new Ada.Containers.Vectors
     (Index_Type   => Positive,
      Element_Type => US.Unbounded_String);

   use type Ada.Containers.Count_Type;

   function Less (Left, Right : US.Unbounded_String) return Boolean is
      L : constant String := US.To_String (Left);
      R : constant String := US.To_String (Right);
      M : constant SM.Character_Mapping := SM.To_Mapping
        (From => "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
         To   => "abcdefghijklmnopqrstuvwxyz");
   begin
      if L'Length /= R'Length then
         return L'Length > R'Length;
      else
         declare
            LL : constant String := SF.Translate (L, M);
            RR : constant String := SF.Translate (R, M);
         begin
            return LL < RR;
         end;
      end if;
   end Less;

   package String_Sorting is new String_Vectors.Generic_Sorting ("<" => Less);

   V : String_Vectors.Vector;
begin
   for I in 1 .. Ada.Command_Line.Argument_Count loop
      V.Append (US.To_Unbounded_String (Ada.Command_Line.Argument (I)));
   end loop;

   String_Sorting.Sort (V);

   if V.Length > 0 then
      for I in V.First_Index .. V.Last_Index loop
         Ada.Text_IO.Put_Line (US.To_String (V (I)));
      end loop;
   end if;
end Main;

